"""Prepare revised academic copy from immutable measured sources."""
import copy
import json
from pathlib import Path
from urllib.parse import quote

ROOT = Path(__file__).resolve().parents[2]
HERE = Path(__file__).resolve().parent
DECK = ROOT / "reports/milestone2_final"


def main():
    content = json.loads((DECK / "slide_content_three_seeds.json").read_text(encoding="utf-8"))
    content = copy.deepcopy(content)
    content["version"] = "strict-review-20261119"
    refs = content["references"]
    commit = "0afd6bf87622e808ce7f730f8556e78229b9e758"
    refs["2"]["url"] = "https://github.com/ZHUANGHP/Analytic-continual-learning/blob/" + commit + "/" + quote("Supplementary Material for DS-AL .pdf")
    refs["2"]["full"] = refs["2"]["full"].replace("Local source: docs/references/DS-AL-supplementary.pdf.", "Supplement A–C, archived with official checkout 0afd6bf.")
    refs["7"] = {"short": "[7] ZHUANGHP, Analytic-continual-learning, GitHub, commit 0afd6bf, truy cập 19/11/2026.",
                 "full": "[7] ZHUANGHP, “Analytic-continual-learning,” official verification code, GitHub, commit " + commit + ", accessed Nov. 19, 2026.",
                 "url": "https://github.com/ZHUANGHP/Analytic-continual-learning/tree/" + commit}
    slides = {s["number"]: s for s in content["slides"]}

    def change(i, title=None, message=None, notes=None, **extra):
        s = slides[i]
        if title is not None: s["title"] = title
        if message is not None: s["message"] = message
        if notes is not None: s["notes"] = notes
        s.update(extra)

    change(4, notes="LwF dùng distillation trên đầu ra cũ ở dữ liệu mới để hạn chế thay đổi hành vi, nhưng phân phối pha mới có thể đại diện yếu cho lớp cũ. Hệ quả là giữ loss distillation nhỏ vẫn có thể phân loại lớp cũ kém. iCaRL giữ exemplar và prototype để hỗ trợ cập nhật biểu diễn/phân loại; lợi ích là truy cập mẫu cũ, đổi lại cần bộ nhớ ảnh và không thỏa exemplar-free. ACIL giải ridge trên embedding cố định bằng thống kê, tránh đọc lại ảnh cũ và giữ nghiệm bằng joint ridge, nhưng đóng băng backbone làm khả năng nhận lớp mới phụ thuộc biểu diễn base. DS-AL bổ sung một embedding và head residual để tăng lớp hàm score có thể khớp. Đây là phân tích cơ chế, không phải kết quả nhóm đã chạy LwF/iCaRL. Chi phí được so sánh ở slide20: SGD còn cần backward nhiều epoch, ACIL một trạng thái m², DS-AL hai, replay thêm M ảnh.")
    change(5, notes="Tác giả gọi đóng góp lý thuyết là Concatenated Recursive Least Squares (C-RLS), kỹ thuật là Dual-Activation Compensation (DAC) cùng Previous Label Cleansing (PLC), thực nghiệm là so sánh exemplar-free/replay và các cấu hình số pha. ACIL đã có ý tưởng analytic learning và equivalence trên embedding cố định; không nhận RLS là thuật toán do DS-AL phát minh. Điểm DS-AL nhấn mạnh là biểu diễn mở rộng nhãn bằng concatenation và thiết kế thêm stream học residual qua activation khác, thay vì chỉ một main ridge. PLC áp cấu trúc lớp rời nhau vào residual. Tính mới kỹ thuật không tự bảo đảm accuracy tăng: bảng CIFAR của nhóm cho thấy DAC không PLC không tăng mean A_K. Paper còn thử ImageNet-Full 500 pha; nhóm không chạy phần đó. Chỉ định lý main head là bảo đảm đại số, còn các lợi ích accuracy là quan sát thực nghiệm.")
    change(8, title="Bài toán CIL và hệ ký hiệu", message="Dữ liệu đến theo lớp rời nhau; dự đoán trên toàn bộ không gian nhãn tích lũy", notes="Tại pha k=0,…,K, D_k={(x_i,y_i)} gồm n_k mẫu với y_i thuộc tập lớp mới L_k; L_i giao L_j rỗng khi i khác j. C_k là hợp L_0,…,L_k và c_k=|C_k|. Bộ phân loại h_k ánh xạ ảnh vào C_k, không được biết task ID lúc dự đoán. Huấn luyện pha k chỉ đọc D_k và trạng thái S_{k−1}; không replay D_0,…,D_{k−1}. Mục tiêu đánh giá là giảm lỗi 0–1 trên test của mọi lớp đã thấy, không chỉ L_k. Trong DS-AL, S giữ CNN/B cố định cùng thống kê và hai head. Ký hiệu f(x) thuộc R^d, B có d×m, X_M,k và X_C,k có n_k×m, Y_k có n_k×c_k theo chỉ số toàn cục; W có m×c_k, G/R có m×m. Nhánh chính thay tối ưu accuracy trực tiếp bằng ridge surrogate trên embedding cố định, được giải thích ở slide11. Không giả định toàn DS-AL tối ưu một objective joint ridge chung với residual đã được tái tính cho mọi pha.")
    change(10, notes=slides[10]["notes"].replace("Khác biệt phân phối projection chưa được PDF mô tả đầy đủ là một giả thuyết cần kiểm chứng khi phân tích gap.", "PDF không chốt phân phối projection đủ chi tiết. Checkout 0afd6bf của tác giả dùng RandomBuffer kế thừa Linear.reset_parameters: Uniform(−1/√d,+1/√d), không bias. Với d=64, biên là ±0,125. Nhóm dùng Normal(0,1), không bias: đây là khác biệt implementation đã xác minh, chưa phải nguyên nhân gap được chứng minh bằng can thiệp kiểm soát."), refs=["1","7"])
    change(16, notes=slides[16]["notes"] + " Có K+1 lần finalize nếu tính cả base. Với c lớp, chi phí stats đầy đủ gồm O(Nm²+Nmc+(K+1)(m³+m²c)) cho mỗi stream, ngoài O(Ndm) để tạo projection. ACIL dùng một stream, DS-AL hai stream nên có thêm hằng số và pass residual. Bậc chi phí main không chứng minh tổng runtime DS-AL nhanh hơn replay trên mọi máy.")
    change(17, message="Residual của từng pha dùng nghiệm main cuối pha; ridge không tạo null space trực giao chính xác", notes="Algorithm1 yêu cầu hoàn tất main stream của pha k rồi mới tạo E_k=Y_k−X_M,k W_M,k, áp PLC và fit compensation bằng X_C,k. Residual của những pha trước được giữ như lúc chúng được tạo, không tái tính mỗi khi W_M thay đổi. Vì vậy DAC không kế thừa ngay tính bất biến pha của nhãn one-hot cố định. Với X=X_M,0:k và E_joint=Y_0:k−XW_M,k ở nghiệm ridge, điều kiện chuẩn là XᵀE_joint=γW_M,k. Do γ>0, residual nói chung không trực giao chính xác với không gian cột X. Không áp đẳng thức này riêng cho X_M,kᵀE_k vì W_M,k được fit trên toàn lịch sử. Cụm null space trong paper chỉ được trình bày như trực giác: activation khác có thể biểu diễn phần main chưa khớp. Nó không phải một định lý trực giao hay bảo đảm tăng accuracy. Unit test kiểm tra đúng normal equations bằng float64; ví dụ PLC ở slide18 là minh họa đại số, không phải dữ liệu nghiên cứu.")
    change(20, notes=slides[20]["notes"] + " So với LwF, backbone còn được cập nhật bằng SGD và distillation: chi phí phụ thuộc E epoch và chi phí forward/backward CNN, trạng thái cần mạng teacher hoặc đầu ra/weights cũ. Với ACIL trên cùng m/dtype, chỉ một stream nên ma trận tương quan chiếm 512 MiB. iCaRL còn giữ M ảnh/prototype và cần cập nhật biểu diễn, bộ nhớ exemplar O(M·kích thước ảnh). Không gán một hệ số thời gian thực đo chung khi chưa chạy những baseline này.")
    change(22, message="Core: đối sánh Table 1 và sensitivity Tanh/C của Figure 4; buffer là phân tích nhóm", notes="Chọn Core vì ImageNet-Full/500 pha vượt ngân sách máy16GB và hạn học phần. E1 là so sánh ACIL/DS-AL CIFAR-100 B50 ResNet32 K5 qua ba seed; khảo sát K25/50 bổ sung phần cùng dataset của Table1 ở seed0. E4 mới phân tích sensitivity C=0,1,…,1 với Tanh trên ba classifier đã lưu, cộng C=0 làm control; tương ứng nhánh Tanh/CIFAR của Figure4, không tái hiện các activation/dataset còn lại. C chỉ nhân score ở inference, nên không cần refit head. E2 là ablation DAC/PLC chuyển từ ImageNet-Full/C=1,4 sang CIFAR/C=0,6; giữ vai trò bằng chứng cơ chế, không nhận tái hiện nguyên Table2. E3 là phân tích buffer/accuracy/thời gian do nhóm thiết kế trên seed0. Hai phần paper quan trọng được đưa ra để giảng viên đánh giá là headline và sensitivity C; mức độ đủ của Core vẫn là đánh giá học thuật, không tự nhận đã được chấp thuận. Full scope và ImageNet chưa hoàn tất.")
    change(24, message="21 kiểm thử và audit artifact; mã tác giả chỉ chạy trong đối chiếu riêng", notes=slides[24]["notes"].replace("15 kiểm thử", "21 kiểm thử") + " Sáu trường hợp mới bổ sung inverse class order, projection seed cục bộ, multi-phase chunk consistency cho cả hai solver, C=0 về main score, accuracy có trọng số theo số mẫu và paired corrected/harmed counts, và normal equations của ridge residual. Tổng21 trường hợp pytest đạt. Audit thêm24 run finished với config/summary/history đọc công khai không xác thực. Đối chiếu ResNet32 cùng weights trên bốn input tổng hợp bằng float64 cho sai số feature1,14e-13; chỉ kiểm tra forward architecture, không chứng minh quỹ đạo training giống tác giả.")
    change(25, message="Các so sánh dùng chung biểu diễn trong từng seed; sensitivity C giữ nguyên classifier", notes=slides[25]["notes"] + " E4 là phân tích hậu nghiệm trên cùng classifier final K5 và test cố định, C=0,6 vẫn là giá trị benchmark đã chọn theo paper. Mỗi seed có run sensitivity riêng chứa hash classifier/cache/checkpoint và parent run IDs. Không tính lại A-bar cho các C khác vì không lưu classifier tại mọi pha, chỉ có final heads. Không gộp các C như các seed độc lập.")
    change(28, notes=slides[28]["notes"] + " Gain A_K của paper là58,26−57,78=0,48pp; gain nhóm là56,7733−56,3700=0,4033pp, thấp hơn0,0767pp. Hai gain gần nhau về độ lớn và cùng chiều là quan sát tương đối đáng chú ý, dù accuracy tuyệt đối thấp hơn. Không suy ra gap chỉ đến từ backbone, vì ảnh hưởng của projection, class order và residual có thể tương tác. Cần ablation giữ nguyên backbone/cache để tách các yếu tố.")
    change(29, notes=slides[29]["notes"] + " DAC−ACIL: base mean giảm4,4267pp, novel mean tăng4,2933pp, cân bằng hai nhóm test cho tổng−0,0667pp. PLC so DAC: base tăng2,2933pp, novel giảm1,3533pp, tổng+0,4700pp. Paper Table2 ImageNet-Full cho DAC+1,32pp và PLC+0,74pp A_K; khác dataset/C nên không dùng chênh này để suy ra code sai. Paired prediction flips từ classifier thật bổ sung ở slide40.")
    change(31, title="Số pha K đối sánh trực tiếp Table 1", message="Cùng ResNet-32/B50; nhóm chỉ seed 0 ở K=5/25/50, paper là mean", notes="Table1 DS-AL ResNet32: K5/25/50 có A-bar66,39/66,20/66,33 và A_K58,26/58,32/58,37%. Nhóm seed0 có A-bar65,8219/65,5433/65,5361 và A_K56,87/56,83/56,87%. Gap A_K tương ứng−1,39/−1,49/−1,50pp; gap A-bar−0,5681/−0,6567/−0,7939pp. Audit xác nhận cùng checkpoint/cache/class order/projection/analytic settings, chỉ thay số pha. K5/K25/K50 có6/26/51 điểm đánh giá. Khoảng dao động A_K nhóm0,04pp hỗ trợ quan sát ổn định trên realization này, không chứng minh compensation weights hoặc score bất biến. A-bar khác vì các tập lớp trung gian và số lần đánh giá khác. Không lấy mean ba seed K5 thay cho hàng seed0 trong khảo sát K. Đây là đối sánh một phần Table1, không là thí nghiệm ImageNet500 pha.")
    change(34, title="Những khác biệt đã xác minh", message="Khác biệt với checkout đã được kiểm tra; nguyên nhân gap với paper chưa xác lập", notes="SupplementC mô tả160 epoch, SGD0,1 giảm tại80/120, momentum0,9, weight decay5e-4, batch128, crop/flip/normalize; nhóm theo cấu hình này. README checkout hiện tại dùng300 epoch/cosine/LR0,5 và TrivialAugment, còn nói paper không augment, mâu thuẫn SupplementC. Không dùng số trong README làm mốc paper. Các khác biệt với checkout đã xác minh: projection Uniform±1/√d so Normal(0,1); class-order Python Random so NumPy RandomState; init Conv Kaiming fan_in so fan_out và init Linear khác; std normalization khác nhẹ; residual cập nhật theo minibatch trong code so full-phase Algorithm1; RLS so stats/Cholesky. Chia loại: match paper đã xác minh cho các hyperparameter được nêu; implementation differences đã xác minh với checkout; ảnh hưởng định lượng và thiết lập thật của từng run paper còn chưa xác minh. Forward ResNet32 được kiểm tra với cùng weights bằng float64 và khớp, nhưng init/training chưa đồng nhất. Không suy diễn bất kỳ khác biệt nào là nguyên nhân gap. Kế hoạch can thiệp riêng cho projection/residual/backbone nằm trong báo cáo, chưa chạy các refit nặng.", refs=["1","2","7"])
    change(35, notes=slides[35]["notes"] + " Sensitivity mới cho C=0…1 trên final Tanh heads có mean A_K cao nhất56,83 ở C0,7/0,8; C0,6 đã chọn trước vẫn giữ trong bảng benchmark. Xu hướng tăng rồi giảm gợi ý có đánh đổi, không chứng minh optimum tổng quát. Chi tiết figure36 và base/novel figure40. Các giới hạn đủ Core và host Forge vẫn cần giảng viên đánh giá.")
    change(13, notes=slides[13]["notes"] + " Chi tiết gain được gộp từ phụ lục cũ: " + slides[36]["notes"])
    change(36, title="Sensitivity C trên classifier đã lưu", message="Tanh, CIFAR-100 B50/K5; mean ± SD ba seed, chỉ đánh giá pha cuối", kind="ratio_sensitivity", section="Thực nghiệm bổ sung", runs=[], seedMethods=[], analysisRuns=True,
           notes="C chỉ xuất hiện trong score S=S_M+C·S_C, không tham gia tạo residual hay fit head. Vì vậy giữ classifier final rồi sweep C tương đương thay C ở inference của cùng thí nghiệm, không cần train lại. Script analyze_saved_classifiers đọc classifier/cache theo SHA-256, xác nhận C0 khớp ACIL và C0,6 khớp DS-AL cũ cho accuracy tổng/base/novel từng seed, rồi mới log11 điểm C0…1 vào ba run sensitivity. Nhánh Tanh/CIFAR của Figure4 paper cho dạng tăng rồi giảm với đỉnh quanh0,6; nhóm đạt mean A_K56,37 tại0,56,77 tại0,6,56,83 tại0,7/0,8 và56,60 tại1. Đây là đối sánh xu hướng, không số hóa các điểm không có nhãn của paper. Error bar là SD mẫu của ba seed, không CI. Chênh đỉnh nhỏ hơn SD không phải kiểm định. Không thay benchmark C0,6 bằng điểm test tốt nhất; đây là phân tích hậu nghiệm trên test, không chọn hyperparameter cho mô hình triển khai. Chỉ có final classifier, nên không suy ra A-bar hay đường học pha cho các C khác. Không nhận tái hiện toàn Figure4 hoặc nhiều activation.", refs=["1"])
    change(37, notes=slides[37]["notes"] + " Đọc trực tiếp DSAL.fit cho thấy main_stream.update được gọi bên trong mỗi minibatch trước khi tính Y_comp, nên ở chunk4 residual được tạo bởi năm main head trung gian mỗi pha. Nhóm giữ main final-phase cho mọi chunk. Đây là vị trí sai khác đã xác minh ở checkout này. Benchmark CIFAR dùng nhiều minibatch nhưng chưa có can thiệp đổi riêng ngữ nghĩa trên cùng cache ở kích thước8192; ảnh hưởng accuracy chưa đo. Không xem chênh head trên input tổng hợp là số pp accuracy.", refs=["1","2","7"])
    change(40, title="DAC và PLC: đánh đổi base / novel", message="Pha cuối có 5.000 ảnh base và 5.000 ảnh novel; mean ± SD của ba seed", kind="base_novel_analysis", runs=[], seedMethods=["acil-k5","dac-no-plc-k5","dsal-k5"], analysisSources=True,
           notes="Từ summaries và kiểm tra lại classifier, mean base/novel của ACIL68,2933/44,4467; DAC không PLC63,8667/48,7400; DS-AL66,1600/47,3867%. Do hai nhóm đều5.000 ảnh, A_K=(base+novel)/2 trong mỗi seed. DAC−ACIL base−4,4267pp, novel+4,2933pp, tổng−0,0667pp: tăng plasticity chưa bù được mất stability trong cấu hình này. PLC−DAC base+2,2933pp, novel−1,3533pp, tổng+0,4700pp: tác dụng đo được là cân lại đánh đổi, không làm cả hai nhóm tăng. Paired flips xác nhận DS-AL so ACIL sửa195/204/219 dự đoán sai và làm hỏng164/170/163 dự đoán đúng ở seed0/1/2; net31/34/56 trên10.000 ảnh đúng với+0,31/+0,34/+0,56pp. Script lưu counts cho DAC/PLC và hai nhóm, không cần refit. Không đánh đồng counts pooled30.000 ảnh với30.000 mẫu độc lập cho kiểm định vì ba seed dùng cùng tập ảnh. Train residual lịch sử không được lưu từng pha; không thể phục dựng norm của tất cả residual từ final heads mà không tính lại các pha. Do đó không tạo biểu đồ residual lịch sử giả.", refs=["1"])

    # Existing mathematical sources remain; refresh native citations and append
    # public evidence paths so notes do not depend solely on ignored outputs/.
    for s in content["slides"]:
        if s.get("seedMethods"):
            s["notes"] += " Bằng chứng nhẹ tương ứng nằm trong experiments/multiseed/20261119/evidence/seed{0,1,2}/; mapping đầy đủ ở reports/strict_review/EXPERIMENT_MAPPING.md."
    ordered = []
    for s in content["slides"]:
        for ref in s["refs"]:
            if ref not in ordered: ordered.append(ref)
    numbers = {old: str(i + 1) for i, old in enumerate(ordered)}
    new_refs = {}
    for old in ordered:
        item = dict(refs[old]); new = numbers[old]
        item["short"] = item["short"].replace("[" + old + "]", "[" + new + "]", 1)
        item["full"] = item["full"].replace("[" + old + "]", "[" + new + "]", 1)
        new_refs[new] = item
    content["references"] = new_refs
    for s in content["slides"]: s["refs"] = [numbers[r] for r in s["refs"]]
    content["citation_renumbering"] = numbers
    (DECK / "slide_content_strict.json").write_text(json.dumps(content, ensure_ascii=False, indent=2), encoding="utf-8")
    print("Prepared 40 reviewed slides; original content/data unchanged")


if __name__ == "__main__":
    main()
